#version 330
out vec4 fragColor;in vec2 fragCoord;uniform float elapsed;uniform vec2 resolution;vec3 b(in vec3 d){vec3 e=clamp(abs(mod(d.x*6.+vec3(.0,4.,2.),6.)-3.)-1.,.0,1.);return d.z+d.y*(e-.5)*(1.-abs(2.*d.z-1.));}void main(){float f=50.;float g=elapsed*.1;vec3 h=vec3(g,.4,.6);vec3 i=b(h);vec3 j=b(vec3(h.x,h.y,h.z));vec3 k=b(vec3(h.x+.5,h.y,h.z));vec2 l=(fragCoord-(resolution.xy/2.));float m=length(l);float n=100.;float o=n*(n/m);vec2 q=vec2(l.x*o/m+cos(elapsed*.9)*700.,l.y*o/m+sin(elapsed*.8)*400.);float r=cos(elapsed*.5)*.5+.5;q.x=l.x+r*(q.x-l.x);q.y=l.y+r*(q.y-l.y);if(abs(q.x)>resolution.x/.5 || abs(q.y)>resolution.y/.5){fragColor=vec4(1.);return;}int u=int(floor(q.x/f));if(u<0)u=-u;int v=int(floor(q.y/f));if(v<0)v=-v;if(u % 2==v % 2){fragColor=vec4(j,1.);}else{fragColor=vec4(k,1.);;}return;}